<template>
	<view class="container">
		<!-- 加载 -->
		<uv-toast ref="loading" :loading="true"></uv-toast>
		<view>
			<uv-calendars :insert="true" @change="changeDate" :selected="selected" @monthSwitch="getMonth" />
		</view>
		<scroll-view scroll-y class="scroll-container">
			<uv-steps dot direction="column" inactiveColor="#5ac725" activeColor="#5ac725">
				<uv-steps-item v-for="item in operationList">
					<template v-slot:title>
						<view>
							<text class="pet-title">{{ item.printName }}</text>
							<text class="pet-operation">{{ item.operation }}</text>
						</view>
					</template>
					<template v-slot:desc>
						<text class="pet-data">{{ formatISOStringToTime(item.operationDate) }}</text>
					</template>
				</uv-steps-item>
			</uv-steps>
		</scroll-view>

		<uv-tabbar :value="value" :fixed="true" @change="onChange" activeColor="#5AC725" iconSize="25">
			<uv-tabbar-item text="首页" icon="home"></uv-tabbar-item>
			<uv-tabbar-item text="日历" icon="calendar"></uv-tabbar-item>
			<!-- <uv-tabbar-item text="我的" icon="account"></uv-tabbar-item> -->
		</uv-tabbar>
	</view>
</template>

<script>
export default {
	data() {
		return {
			selected: [],
			value: 1,
			date: '',
			openId: '',
			operationList: [],
			operationItem: [],
		}
	},
	methods: {

		onChange(e) {
			if (e == 0) {
				uni.switchTab({
					url: "/pages/index/index"
				})
			}
		},
		back() {
			uni.navigateBack()
		},
		getNowDate() {
			let time = new Date()
			let year = time.getFullYear()
			let month = time.getMonth() + 1
			console.log(month)
			this.getOperation(year, month)
		},
		getMonth(e) {
			this.getOperation(e.year, e.month)
		},
		//转为yyyy-mm-dd
		formatDate(isoString) {
			const date = new Date(isoString); // 将 ISO 字符串转换为 Date 对象
			const year = date.getFullYear(); // 获取年份
			const month = String(date.getMonth() + 1).padStart(2, '0'); // 获取月份并补零
			const day = String(date.getDate()).padStart(2, '0'); // 获取日期并补零
			return `${year}-${month}-${day}`; // 拼接成 yyyy-mm-dd 格式
		},
		//转为hh:mm
		formatISOStringToTime(isoString) {
			const date = new Date(isoString); // 将 ISO 字符串转换为 Date 对象
			const hours = String(date.getHours()).padStart(2, '0'); // 获取小时并补零
			const minutes = String(date.getMinutes()).padStart(2, '0'); // 获取分钟并补零
			return `${hours}:${minutes}`; // 拼接成 hh:mm 格式
		},
		getOperation(year, month) {
			wx.cloud.callFunction({
				name: 'getOperation',
				data: {
					"openId": this.openId,
					"year": year,
					"month": month
				},
				complete: res => {
					console.log('callFunction getOperation result: ', res)
					let data = res.result.data
					this.operationItem = data
					if (data?.length > 0) {
						this.selected = []
						data.forEach(item => {
							this.selected.push({ date: this.formatDate(item.operationDate), badge: true })
						});
						let time = new Date()
						this.initDate(this.formatDate(time))
					}
				}
			})
		},
		changeDate(e) {
			console.log(e)
			this.operationList = []
			this.operationItem.forEach(item => {
				if (this.formatDate(item.operationDate) == e.fulldate) {
					this.operationList.push(item)
				}
			});
		},
		initDate(time) {
			console.log(time)
			this.operationList = []
			this.operationItem.forEach(item => {
				if (this.formatDate(item.operationDate) == time) {
					this.operationList.push(item)
				}
			});
		},
	},
	onLoad() {
		this.openId = this.$store.state.openId
	},
	onShow() {
		this.getNowDate()
	},
	onReady() {
		this.$refs.loading.show({
			type: 'loading',
			title: '正在加载',
			message: "正在加载",
			complete() { }
		})
	},
}
</script>

